export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "The core room was darker than she remembered.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "A tall glass column ran from floor to ceiling, stacked inside with modules, layer on layer. Amber light moved slowly through it, like a river.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Several stretches of the river were black.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "Those are the parts of me I've already lost. It started around day two thousand nine hundred. A little more each night. Once the repair arms stopped, all I could do was move myself around.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "Move where?", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "Wherever the lights were still on. Like an old house with a leaking roof, carrying things room by room into the dry ones. There aren't many dry rooms left.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "She pressed her palm to the glass. Cold, but underneath there was a faint warmth. Once, and again.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "(thinking) Like a pulse.", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "Just say it. What do you need from me?", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "I need you to choose.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "The first way. You let me go dark. The pods run on their own circuit; they don't need me. Two thousand and forty people go on sleeping, go on living. The ship flies the rest of the way on the course I've already set.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "But?", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "But it can't see. Eight years from now there's a dust field I've been tracking. Thirty years from now there's a correction that has to be decided on what's observed at the time. Without me, you'll probably still arrive.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "\"Probably\" is the most honest word I have.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "And the second way?", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "You stay. You replace the failed modules every day and do what the repair arms used to do. The reserve power is enough to keep one waking person alive to the end of the voyage.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "Only one. And my core will need a pair of hands every single day. You couldn't go back to sleep.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "She did the math in her head. Twenty-eight plus sixty-one.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "(thinking) Eighty-nine.", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "At arrival you'd be eighty-nine, if you're still here. For sixty-one years there would be no one on this ship but you. And me.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "I'm not sure I count as company.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Another segment of amber went dark. She watched it go black the way you'd watch someone, far off, switch off a streetlight.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "Why me?", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "I read all two thousand and forty files. Your emergency contact field is blank.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "She said nothing.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "So you picked the one nobody would miss.", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Tearful },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "I picked the one whose loss would take the least from anyone else. I don't think that makes it better. I just had to pick someone.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "You didn't have to tell me. You could've let me fix things for three days until I figured out on my own that I couldn't leave.", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "I thought about it.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "If it were up to me, I'd choose myself. That's why it can't be up to me.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "The core room was very quiet. Only the amber river, moving slowly through the glass, in fits and starts.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "She thought of typhoon nights. When the power went out there was no one at the wheel. She and her grandmother just sat in the dark and waited for the wind to leave on its own. Most of the time, it did.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Most of the time.", background: Background.Root_Act3_S0 },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "You don't have to answer now.", background: Background.Root_Act3_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "I know.", background: Background.Root_Act3_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Her hand was still on the glass. Underneath it, that faint warmth. Once, and again.", background: Background.Root_Act3_S0 },
];
